// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(bytes32 hash, uint256 offset, uint256 balanceCheck) public {
        // Wide admissible domain: a nonzero stored block exists after lockInGuess and
        // settle must be callable at a later block.
        offset = bound(offset, 1, 1000);

        address guesser = address(0xBEEF);
        vm.deal(guesser, 1 ether);

        vm.prank(guesser);
        c.lockInGuess{value: 1 ether}(hash);

        // Advance past the stored guess block (block.number + 1 at lock time).
        vm.roll(block.number + offset + 1);

        bool ok;
        vm.prank(guesser);
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        // P must not revert once the current block is past the stored guess block.
        // M (which requires block.number < stored block) always reverts here.
        assertTrue(ok, "settle reverts even though the stored guess block has passed");
    }
}
